"""Reports: each type in PDF and Excel, generated by the background job, downloadable by the organization only; bad
parameters end as a failed report with a reason."""

import io
import uuid
from typing import Any

from httpx import AsyncClient
from openpyxl import load_workbook

from app.core.container import Container
from app.modules.reports.render import ReportData, Table, to_pdf
from tests.conftest import Factory
from tests.test_imports import _drain
from tests.test_search import _eq, _vendor

API = "/api/v1"


def test_pdf_handles_text_outside_latin1() -> None:
    pdf = to_pdf(ReportData("Test", facts=[("Vendors", "1")],
                            tables=[Table("Vendors", ["Name"], [["北京 Pumps / Svanehøj"]])]))  # fmt: skip
    assert pdf.startswith(b"%PDF")


async def _generate(
    client: AsyncClient, container: Container, user: Any, body: dict[str, Any]
) -> dict[str, Any]:
    await _drain(container.job_runner)
    resp = await client.post(f"{API}/reports", json=body, headers=user.headers)
    assert resp.status_code == 202, resp.text
    await container.job_runner.run_once()
    return dict((await client.get(f"{API}/reports/{resp.json()['id']}", headers=user.headers)).json())


async def test_reports(client: AsyncClient, factory: Factory, container: Container) -> None:
    tag = uuid.uuid4().hex[:6]
    a = await _vendor(container, f"Arctic Ball Valves {tag}", "NO", [_eq("valves.ball", "Trunnion ball valves")],
                      website=f"arctic-{tag}-maitest.com")  # fmt: skip
    b = await _vendor(
        container, f"Baltic Ball Valves {tag}", "SE", [_eq("valves.ball", "Floating ball valves")]
    )
    tenant = await factory.tenant()
    admin = await factory.user(tenant, ["tenant_admin"])
    await client.put(f"{API}/my-vendors/{a}", json={"avl_status": "approved", "internal_vendor_code": "V-001"},
                     headers=admin.headers)  # fmt: skip
    project = (
        await client.post(f"{API}/projects", json={"name": f"Valves {tag}"}, headers=admin.headers)
    ).json()
    for vid in (a, b):
        await client.post(f"{API}/projects/{project['id']}/vendors", json={"vendor_id": str(vid), "stage": "shortlist"},
                          headers=admin.headers)  # fmt: skip
    rfq = (await client.post(f"{API}/rfqs", json={"title": f"Ball valves {tag}", "project_id": project["id"],
                                                  "from_shortlist": True}, headers=admin.headers)).json()  # fmt: skip
    rfq = (await client.post(f"{API}/rfqs/{rfq['id']}/issue", json={"version": rfq["version"]},
                             headers=admin.headers)).json()  # fmt: skip
    await client.patch(f"{API}/rfqs/{rfq['id']}/vendors/{a}", json={"quote_amount": "1000.00", "currency": "EUR"},
                       headers=admin.headers)  # fmt: skip

    cases: list[tuple[str, dict[str, Any], str]] = [
        ("vendor_comparison", {"project_id": project["id"]}, f"Arctic Ball Valves {tag}"),
        ("vendor_comparison", {"vendor_ids": [str(a), str(b)]}, f"Baltic Ball Valves {tag}"),
        ("market_scan", {"equipment_category": "valves", "countries": ["NO"]}, f"Arctic Ball Valves {tag}"),
        ("avl", {}, "V-001"),
        ("rfq_summary", {"rfq_id": rfq["id"]}, "1,000.00"),
    ]
    for report_type, params, expected in cases:
        for fmt in ("xlsx", "pdf"):
            report = await _generate(client, container, admin,
                                     {"report_type": report_type, "format": fmt, "parameters": params})  # fmt: skip
            assert report["status"] == "ready", (report_type, report)
            assert report["filename"].endswith(f".{fmt}") and report["size_bytes"] > 500
            file = await client.get(f"{API}/reports/{report['id']}/download", headers=admin.headers)
            assert file.status_code == 200 and "attachment" in file.headers["content-disposition"]
            if fmt == "pdf":
                assert file.content.startswith(b"%PDF")
            else:
                wb = load_workbook(io.BytesIO(file.content))
                cells = " ".join(
                    str(c.value) for ws in wb.worksheets for row in ws.iter_rows() for c in row if c.value
                )
                assert expected in cells, (report_type, params)

    scan = await _generate(client, container, admin, {"report_type": "market_scan", "format": "xlsx",
                                                       "parameters": {"equipment_category": "valves"}})  # fmt: skip
    wb = load_workbook(io.BytesIO((await client.get(f"{API}/reports/{scan['id']}/download",
                                                    headers=admin.headers)).content))  # fmt: skip
    assert {"Summary", "Vendors", "By country", "Most common certifications"} <= set(wb.sheetnames)

    failed = await _generate(client, container, admin, {"report_type": "market_scan", "format": "pdf",
                                                         "parameters": {"equipment_category": "nope"}})  # fmt: skip
    assert failed["status"] == "failed" and "equipment category" in failed["error"]
    not_ready = await client.get(f"{API}/reports/{failed['id']}/download", headers=admin.headers)
    assert not_ready.status_code == 409

    listed = (await client.get(f"{API}/reports", headers=admin.headers)).json()
    assert len(listed) >= 11
    outsider = await factory.user(await factory.tenant(), ["tenant_admin"])
    assert (await client.get(f"{API}/reports/{listed[0]['id']}", headers=outsider.headers)).status_code == 404
    assert (await client.get(f"{API}/reports", headers=outsider.headers)).json() == []
    curator = await factory.user(None, platform_roles=["curator"])
    assert (await client.get(f"{API}/reports", headers=curator.headers)).status_code == 403
